// Telemetry for the static landing pages under /library/.
//
// Standalone by design: those pages are generated by dataset/generate_seo_pages.py
// and load no other app code, so this cannot reuse js/telemetry-logger.js (which
// assumes the app's own relative paths and globals). The wire format and the
// privacy properties are identical — ephemeral random session id, no storage,
// no cookies. Event names must exist in api/telemetry.php's $ALLOWED_EVENTS.
//
// The script tag carries the page identity:
//   <script defer src="../js/seo-telemetry.js" data-slug="…" data-page-type="…"></script>

(function () {
    const script = document.currentScript ||
        document.querySelector('script[src$="seo-telemetry.js"]');
    const SLUG      = script ? (script.dataset.slug || '') : '';
    const PAGE_TYPE = script ? (script.dataset.pageType || '') : '';

    function generateSessionId() {
        const arr = new Uint8Array(4);
        crypto.getRandomValues(arr);
        return Array.from(arr, function (b) { return b.toString(16).padStart(2, '0'); }).join('');
    }

    function detectBrowser() {
        const ua = navigator.userAgent;
        if (ua.includes('Edg/'))     return 'Edge';
        if (ua.includes('OPR/'))     return 'Opera';
        if (ua.includes('Chrome/'))  return 'Chrome';
        if (ua.includes('Firefox/')) return 'Firefox';
        if (ua.includes('Safari/') && !ua.includes('Chrome/')) return 'Safari';
        return 'Unknown';
    }

    function getReferrerDomain() {
        try { return document.referrer ? new URL(document.referrer).hostname : ''; }
        catch (_) { return ''; }
    }

    const SESSION_ID      = generateSessionId();
    const BROWSER         = detectBrowser();
    const REFERRER_DOMAIN = getReferrerDomain();
    const IS_LOCAL        = ['localhost', '127.0.0.1', ''].includes(window.location.hostname);

    function logEvent(type, payload) {
        if (IS_LOCAL) {
            console.log('[telemetry]', type, payload || {});
            return;
        }
        const body = JSON.stringify({
            event:           type,
            session_id:      SESSION_ID,
            browser:         BROWSER,
            referrer_domain: REFERRER_DOMAIN,
            payload:         payload || {},
        });
        // Beacon, because most of these fire as the visitor navigates away.
        if (navigator.sendBeacon) {
            navigator.sendBeacon('../api/telemetry.php', new Blob([body], { type: 'application/json' }));
        } else {
            fetch('../api/telemetry.php', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: body, keepalive: true,
            }).catch(function () {});
        }
    }

    logEvent('seo_page_view', {
        slug:      SLUG,
        page_type: PAGE_TYPE,
        viewport:  window.innerWidth < 768 ? 'mobile' : 'desktop',
    });

    // Where on the page the click happened, so we can tell a hero CTA from a
    // footer link. Derived from the generated markup's own classes.
    function linkPosition(link) {
        if (link.closest('.site-header')) return 'header';
        if (link.closest('.site-footer')) return 'footer';
        if (link.closest('.related'))     return 'related';
        if (link.closest('.cta'))         return 'hero_cta';
        if (link.closest('.metric-list')) return 'metric_card';
        if (link.closest('.index-grid'))  return 'collection_list';
        return 'other';
    }

    document.addEventListener('click', function (e) {
        const link = e.target.closest && e.target.closest('a[href]');
        if (!link) return;

        const href = link.getAttribute('href') || '';
        const intoApp = href.indexOf('../index.html') === 0;

        logEvent('seo_cta_click', {
            slug:     SLUG,
            href:     href,
            position: linkPosition(link),
            intoApp:  intoApp,
        });

        // Hand the session id to the app so the landing-page view and the visit
        // that follows read as one session. The app strips it from the URL on
        // arrival, so it never survives long enough to be copied or shared.
        // Restored afterwards for the ctrl-click case, where this page stays open.
        if (intoApp) {
            const original = link.getAttribute('href');
            link.setAttribute('href', original + (original.includes('?') ? '&' : '?') + 'sid=' + SESSION_ID);
            setTimeout(function () { link.setAttribute('href', original); }, 0);
        }
    });
}());
